from collections import deque,Counter

def comps(grid,color,diag=False):
 h,w=grid.shape; seen=set(); out=[]
 dirs=[(-1,0),(1,0),(0,-1),(0,1)]
 if diag: dirs += [(-1,-1),(-1,1),(1,-1),(1,1)]
 for r in range(h):
  for c in range(w):
   if grid[r,c]!=color or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); pts=[]
   while q:
    x,y=q.pop();pts.append((x,y))
    for dx,dy in dirs:
     z=(x+dx,y+dy)
     if 0<=z[0]<h and 0<=z[1]<w and z not in seen and grid[z]==color:
      seen.add(z);q.append(z)
   out.append(pts)
 return sorted(out,key=lambda x:-len(x))
for color in (3,5,9):
 print('\nColor',color)
 for comp in comps(T,color):
  print(len(comp), (min(r for r,c in comp), min(c for r,c in comp),max(r for r,c in comp),max(c for r,c in comp)), sorted(comp))

# component shapes; compare exact shapes under translation + D4
from collections import defaultdict

def canonical(pts):
 pts=list(pts)
 trans=[]
 for k in range(8):
  coords=[]
  for r,c in pts:
   if k==0: x,y=r,c
   elif k==1: x,y=r,-c
   elif k==2: x,y=-r,c
   elif k==3: x,y=-r,-c
   elif k==4: x,y=c,r
   elif k==5: x,y=c,-r
   elif k==6: x,y=-c,r
   else: x,y=-c,-r
   coords.append((x,y))
  mr=min(x for x,y in coords); mc=min(y for x,y in coords)
  trans.append(tuple(sorted((x-mr,y-mc) for x,y in coords)))
 return min(trans)
allcomps=[]
for col in sorted(set(T.flatten())-{6}):
 for cc in comps(T,int(col)):
  allcomps.append((int(col),cc))
groups=defaultdict(list)
for col,cc in allcomps: groups[canonical(cc)].append((col,len(cc),(min(r for r,c in cc),min(c for r,c in cc)),sorted(cc)))
for shape, arr in groups.items():
 if len(arr)>1: print(shape,[(x[0],x[1],x[2]) for x in arr])
